const llmOutput = $input.first().json;
const executionStart = $("Merge CV & Job").first().json._execution_start_ms;
const latencyMs = executionStart ? Date.now() - executionStart : 0;

let jsonResult;
try {
  if (typeof llmOutput.output === "string") {
    jsonResult = JSON.parse(llmOutput.output);
  } else if (typeof llmOutput.output === "object" && llmOutput.output !== null) {
    jsonResult = llmOutput.output;
  } else if (llmOutput.json_result) {
    jsonResult = llmOutput.json_result;
  } else {
    throw new Error("Formato inesperado del LLM: " + JSON.stringify(Object.keys(llmOutput)));
  }

  const err = validateLLMResult(jsonResult);
  if (err) throw new Error(err);

  const merged = $("Merge CV & Job").first().json;
  return [{
    candidate_id: merged.candidate_id,
    job_id: merged.job_id,
    json_result: jsonResult,
    model_version: "deepseek-chat",
    prompt_tokens: llmOutput.usage?.prompt_tokens || 0,
    completion_tokens: llmOutput.usage?.completion_tokens || 0,
    latency_ms: latencyMs
  }];
} catch (error) {
  const merged = $("Merge CV & Job").first().json;
  return [{
    candidate_id: merged.candidate_id,
    job_id: merged.job_id,
    json_result: {
      summary: "Error en análisis IA",
      seniority: null,
      score: 0,
      classification: [],
      suggestions: "HOLD: Error del LLM - " + error.message,
      riskLevel: "Medium"
    },
    model_version: "deepseek-chat",
    prompt_tokens: 0,
    completion_tokens: 0,
    latency_ms: latencyMs,
    prompt_template_id: "cv-evaluator-v1.0"
  }];
}

function validateLLMResult(r) {
  if (!r || typeof r !== "object") return "Resultado no es un objeto";
  if (typeof r.summary !== "string" || !r.summary) return "summary inválido";
  const VALID_SEN = ["Junior", "Semi-Senior", "Senior"];
  if (!VALID_SEN.includes(r.seniority)) return "seniority inválido: " + r.seniority;
  if (!Number.isInteger(r.score) || r.score < 0 || r.score > 100) return "score inválido: " + r.score;
  if (!Array.isArray(r.classification) || r.classification.length === 0) return "classification inválido";
  const validPrefixes = ["ADVANCE:", "INTERVIEW:", "TEST:", "HOLD:", "DISCARD:"];
  if (typeof r.suggestions !== "string" || !validPrefixes.some(p => r.suggestions.startsWith(p))) {
    return "suggestions debe empezar con " + validPrefixes.join(", ");
  }
  const VALID_RISK = ["Low", "Medium", "High"];
  if (!VALID_RISK.includes(r.riskLevel)) return "riskLevel inválido: " + r.riskLevel;
  return null;
}
